#!/usr/bin/env node
// Builds llms.txt (curated index) and llms-full.txt (full concatenation) from
// the per-page markdown generated by scripts/generate-page-md.js. Must run
// after generate:page-md so the outputs never go stale. EN pages only.
// Run with --self-test to check the header parser on samples first.

import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(__dirname, '..');
const MD_DIR = path.join(ROOT, 'public/docs');
const SITE = 'https://mezo.org/docs';

// Parse the header emitted by generate-page-md.js:
//   # Title\n\n_description_\n\n_Source: url_\n\nbody...
function parsePageMd(text) {
  const lines = text.split('\n');
  const title = (lines[0] || '').replace(/^#\s+/, '').trim();
  let i = 1;
  while (i < lines.length && lines[i].trim() === '') i++;
  let description = '';
  const maybeDesc = i < lines.length ? lines[i].trim() : '';
  if (/^_.+_$/.test(maybeDesc) && !maybeDesc.startsWith('_Source:')) {
    description = maybeDesc.replace(/^_/, '').replace(/_$/, '');
    i++;
  }
  while (i < lines.length && lines[i].trim() === '') i++;
  let source = '';
  if (i < lines.length && lines[i].trim().startsWith('_Source:')) {
    source = lines[i].trim().replace(/^_Source:\s*/, '').replace(/_$/, '').trim();
    i++;
  }
  const body = lines.slice(i).join('\n').trim() + '\n';
  return { title, description, source, body };
}

async function walk(dir, out = []) {
  for (const e of await fs.readdir(dir, { withFileTypes: true })) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) await walk(full, out);
    else if (e.name.endsWith('.md')) out.push(full);
  }
  return out;
}

async function main() {
  const files = await walk(MD_DIR);
  if (!files.length) {
    console.error('generate-llms: no .md files in public/docs; run generate:page-md first');
    process.exitCode = 1;
    return;
  }
  const pages = [];
  for (const f of files.sort()) {
    const rel = path.relative(MD_DIR, f).split(path.sep).join('/').replace(/\.md$/, '');
    const group = rel.startsWith('developers/') ? 'Developers' : rel.startsWith('users/') ? 'Users' : 'Other';
    const { title, description, source, body } = parsePageMd(await fs.readFile(f, 'utf-8'));
    if (!title) {
      console.error(`generate-llms: missing title in ${f}`);
      process.exitCode = 1;
      return;
    }
    const url = `${SITE}/${rel}.md`;
    pages.push({ rel, group, title, description, source: source || url, body, url });
  }

  const order = { Users: 0, Developers: 1, Other: 2 };
  pages.sort((a, b) => order[a.group] - order[b.group] || a.title.localeCompare(b.title));

  const index = [
    '# Mezo Documentation',
    '> Official Mezo docs: Bitcoin banking, MUSD borrowing, Mezo Earn, and developer resources.',
    '',
  ];
  let current = '';
  for (const p of pages) {
    if (p.group !== current) {
      current = p.group;
      index.push(`## ${current}`, '');
    }
    index.push(`- [${p.title}](${p.url})` + (p.description ? `: ${p.description}` : ''));
  }
  index.push('');
  await fs.writeFile(path.join(MD_DIR, 'llms.txt'), index.join('\n'), 'utf-8');

  const full = [
    '# Mezo Documentation (full)',
    '> Concatenation of every documentation page in plain markdown.',
    '',
  ];
  for (const p of pages) {
    full.push(`# ${p.title}`, '', `_Source: ${p.source}_`, '', p.body.trim(), '', '---', '');
  }
  await fs.writeFile(path.join(MD_DIR, 'llms-full.txt'), full.join('\n'), 'utf-8');

  console.log(`llms.txt: ${pages.length} entries; llms-full.txt: ${pages.length} pages`);
}

function runSelfTest() {
  const assert = (cond, name) => {
    if (!cond) {
      console.error('SELF-TEST FAIL: ' + name);
      process.exitCode = 1;
    } else {
      console.log('self-test ok: ' + name);
    }
  };
  const a = parsePageMd('# T\n\n_Desc here._\n\n_Source: https://x/y_\n\nBody text.\n');
  assert(a.title === 'T', 'title parsed');
  assert(a.description === 'Desc here.', 'description parsed');
  assert(a.source === 'https://x/y', 'source parsed');
  assert(a.body.trim() === 'Body text.', 'body parsed');
  const b = parsePageMd('# T2\n\n_Source: https://x/z_\n\nBody.\n');
  assert(b.title === 'T2' && b.description === '' && b.source === 'https://x/z', 'missing description tolerated');
  const c = parsePageMd('# T3\n\n_No source line._\n\nBody.\n');
  assert(c.title === 'T3', 'missing source tolerated');
}

if (process.argv.includes('--self-test')) {
  runSelfTest();
} else {
  await main();
}
